def is_golomb(ruler):
    diffs = set()
    for i in range(len(ruler)):
        for j in range(i+1, len(ruler)):
            d = ruler[j] - ruler[i]
            if d in diffs:
                return False
            diffs.add(d)
    return True

def find_golomb(n, max_len):
    import itertools
    for comb in itertools.combinations(range(1, max_len+1), n-1):
        ruler = [0] + list(comb)
        if is_golomb(ruler):
            return ruler
    return None

print(find_golomb(6, 20))
